mapper.select:
SELECT * FROM stock_daily_price
WHERE stock_id = #{stockId} AND trading_date BETWEEN #{from} AND #{to}
ORDER BY trading_date DESC

SELECT * FROM stock_news
WHERE stock_id = #{stockId}
ORDER BY published_at DESC NULLS LAST, id DESC
LIMIT #{limit}

SELECT * FROM stock_disclosure
WHERE stock_id = #{stockId} AND received_at BETWEEN #{from} AND #{to}
ORDER BY received_at DESC, receipt_number DESC
LIMIT #{limit}

SELECT * FROM stock_financial
WHERE stock_id = #{stockId} AND business_year = #{businessYear}
  AND report_code = #{reportCode} AND statement_type = 'CFS'
